// Parse natural language to SQL
const message = $input.item.json.message.toLowerCase();

// Common query patterns
const patterns = {
  'total sales': 'SELECT SUM(total_price) FROM sales',
  'low stock': 'SELECT * FROM products WHERE stock < 10',
  'recent sales': 'SELECT * FROM sales ORDER BY date DESC LIMIT 5',
  'product count': 'SELECT COUNT(*) FROM products',
  'category sales': 'SELECT category, SUM(total_price) FROM products JOIN sales ON products.id = sales.product_id GROUP BY category'
};

// Find matching pattern
let sqlQuery = '';
for (const [pattern, query] of Object.entries(patterns)) {
  if (message.includes(pattern)) {
    sqlQuery = query;
    break;
  }
}

// If no pattern matches, use a default response
if (!sqlQuery) {
  return {
    response: 'I can help you with queries about total sales, low stock items, recent sales, product count, and category sales. Please try asking about one of these topics.'
  };
}

return {
  response: `Here's the SQL query for your request:\n\n\`\`\`sql\n${sqlQuery}\n\`\`\``
};
